  3	import com.pousada.mare_alta.database.Database;
  4	import com.pousada.mare_alta.http.AppRoutes;
  5	import com.pousada.mare_alta.repository.MessageRepository;
  6	import com.pousada.mare_alta.repository.ReservationRepository;
  7	import com.pousada.mare_alta.repository.RoomRepository;
  8	import com.pousada.mare_alta.service.ReportService;
  9	import com.pousada.mare_alta.service.ReservationService;
 10	import io.javalin.Javalin;
 11	
 12	public class Main {
 13	    public static void main(String[] args) throws Exception {
 14	        // Load environment variables
 15	        String dbUrl = System.getenv("DB_URL");
 16	        String dbUser = System.getenv("DB_USER");
 17	        String dbPassword = System.getenv("DB_PASSWORD");
 18	        String portStr = System.getenv("PORT");
 19	
 20	        if (dbUrl == null || dbUser == null || dbPassword == null) {
 21	            throw new RuntimeException("Missing database environment variables: DB_URL, DB_USER, DB_PASSWORD");
 22	        }
 23	
 24	        int port = portStr != null ? Integer.parseInt(portStr) : 7070;
 25	
 26	        // Initialize database
 27	        Database database = new Database(dbUrl, dbUser, dbPassword);
 28	        database.initialize();
 29	
 30	        // Initialize repositories
 31	        RoomRepository roomRepository = new RoomRepository(database);
 32	        ReservationRepository reservationRepository = new ReservationRepository(database);
 33	        MessageRepository messageRepository = new MessageRepository(database);
 34	
 35	        // Initialize services
 36	        ReservationService reservationService = new ReservationService(
 37	                reservationRepository, roomRepository, messageRepository);
 38	        ReportService reportService = new ReportService(reservationRepository, roomRepository);
 39	
 40	        // Setup routes
 41	        AppRoutes appRoutes = new AppRoutes(
 42	                reservationService, reportService, roomRepository, messageRepository);
 43	
 44	        // Create and start Javalin app
 45	        Javalin app = Javalin.create().start(port);
 46	        appRoutes.setupRoutes(app);
 47	
 48	        System.out.println("Server started on port " + port);
 49	    }
 50	}
 51	package com.pousada.mare_alta.http;
 52	
 53	import com.fasterxml.jackson.databind.ObjectMapper;
 54	import com.pousada.mare_alta.http.request.CreateReservationRequest;
 55	import com.pousada.mare_alta.http.response.DocumentResponse;
 56	import com.pousada.mare_alta.http.response.ErrorResponse;
 57	import com.pousada.mare_alta.http.response.MessageResponse;
 58	import com.pousada.mare_alta.http.response.ReservationResponse;
 59	import com.pousada.mare_alta.http.response.RoomResponse;
 60	import com.pousada.mare_alta.model.RatePlan;
 61	import com.pousada.mare_alta.service.ReportService;
 62	import com.pousada.mare_alta.service.ReservationService;
 63	import com.pousada.mare_alta.repository.MessageRepository;
 64	import com.pousada.mare_alta.repository.ReservationRepository;
 65	import com.pousada.mare_alta.repository.RoomRepository;
 66	import io.javalin.Javalin;
 67	import java.math.BigDecimal;
 68	import java.time.LocalDate;
 69	
 70	public class AppRoutes {
 71	    private final ReservationService reservationService;
 72	    private final ReportService reportService;
 73	    private final RoomRepository roomRepository;
 74	    private final MessageRepository messageRepository;
 75	    private final ObjectMapper objectMapper;
 76	
 77	    public AppRoutes(
 78	            ReservationService reservationService,
 79	            ReportService reportService,
 80	            RoomRepository roomRepository,
 81	            MessageRepository messageRepository) {
 82	        this.reservationService = reservationService;
 83	        this.reportService = reportService;
 84	        this.roomRepository = roomRepository;
 85	        this.messageRepository = messageRepository;
 86	        this.objectMapper = new ObjectMapper();
 87	    }
 88	
 89	    public void setupRoutes(Javalin app) {
 90	        // GET /rooms
 91	        app.get("/rooms", ctx -> {
 92	            try {
 93	                var rooms = roomRepository.findAll();
 94	                ctx.json(rooms.stream().map(RoomResponse::fromModel).toList());
 95	            } catch (Exception e) {
 96	                ctx.status(500).json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
 97	            }
 98	        });
 99	
100	        // POST /reservations
101	        app.post("/reservations", ctx -> {
102	            try {
103	                CreateReservationRequest req = ctx.bodyAsClass(CreateReservationRequest.class);
104	                validateCreateReservationRequest(req);
105	
106	                LocalDate checkIn = LocalDate.parse(req.checkIn);
107	                LocalDate checkOut = LocalDate.parse(req.checkOut);
108	                RatePlan ratePlan = RatePlan.fromValue(req.ratePlan);
109	
110	                var reservation = reservationService.createReservation(
111	                        req.roomNumber, req.guestName, req.guestEmail,
112	                        req.guestCpf, req.companyCnpj, req.companyName,
113	                        req.guestPassport, req.guestCountry,
114	                        checkIn, checkOut, req.guests, ratePlan);
115	
116	                ctx.status(201).json(ReservationResponse.fromModel(reservation));
117	            } catch (IllegalArgumentException e) {
118	                if (e.getMessage().contains("Room not found")) {
119	                    ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", e.getMessage()));
120	                } else if (e.getMessage().contains("room capacity")) {
121	                    ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", e.getMessage()));
122	                } else if (e.getMessage().contains("not available")) {
123	                    ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", e.getMessage()));
124	                } else if (e.getMessage().contains("identification") ||
125	                           e.getMessage().contains("Check-out") ||
126	                           e.getMessage().contains("guest")) {
127	                    ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
128	                } else {
129	                    ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
130	                }
131	            } catch (Exception e) {
132	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
133	            }
134	        });
135	
136	        // GET /reservations/{id}
137	        app.get("/reservations/:id", ctx -> {
138	            try {
139	                long id = Long.parseLong(ctx.pathParam("id"));
140	                var reservation = reservationService.getReservation(id);
141	                ctx.json(ReservationResponse.fromModel(reservation));
142	            } catch (IllegalArgumentException e) {
143	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
144	            } catch (Exception e) {
145	                ctx.status(500).json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
146	            }
147	        });
148	
149	        // POST /reservations/{id}/confirmation
150	        app.post("/reservations/:id/confirmation", ctx -> {
151	            try {
152	                long id = Long.parseLong(ctx.pathParam("id"));
153	                var body = ctx.bodyAsClass(java.util.Map.class);
154	                BigDecimal amountPaid = new BigDecimal(body.get("amountPaid").toString());
155	
156	                var reservation = reservationService.confirmReservation(id, amountPaid);
157	                ctx.json(ReservationResponse.fromModel(reservation));
158	            } catch (IllegalArgumentException e) {
159	                if (e.getMessage().contains("not found")) {
160	                    ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
161	                } else {
162	                    ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
163	                }
164	            } catch (Exception e) {
165	                ctx.status(500).json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
166	            }
167	        });
168	
169	        // POST /reservations/{id}/cancellation
170	        app.post("/reservations/:id/cancellation", ctx -> {
171	            try {
172	                long id = Long.parseLong(ctx.pathParam("id"));
173	                var reservation = reservationService.cancelReservation(id);
174	                ctx.json(ReservationResponse.fromModel(reservation));
175	            } catch (IllegalArgumentException e) {
176	                if (e.getMessage().contains("not found")) {
177	                    ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
178	                } else {
179	                    ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
180	                }
181	            } catch (Exception e) {
182	                ctx.status(500).json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
183	            }
184	        });
185	
186	        // POST /reservations/{id}/check-in
187	        app.post("/reservations/:id/check-in", ctx -> {
188	            try {
189	                long id = Long.parseLong(ctx.pathParam("id"));
190	                var reservation = reservationService.checkIn(id);
191	                ctx.json(ReservationResponse.fromModel(reservation));
192	            } catch (IllegalArgumentException e) {
193	                if (e.getMessage().contains("not found")) {
194	                    ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
195	                } else {
196	                    ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
197	                }
198	            } catch (Exception e) {
199	                ctx.status(500).json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
200	            }
201	        });
202	
203	        // POST /reservations/{id}/check-out
204	        app.post("/reservations/:id/check-out", ctx -> {
205	            try {
206	                long id = Long.parseLong(ctx.pathParam("id"));
207	                var document = reservationService.checkOut(id);
208	                ctx.json(DocumentResponse.fromModel(document));
209	            } catch (IllegalArgumentException e) {
210	                if (e.getMessage().contains("not found")) {
211	                    ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
212	                } else {
213	                    ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
214	                }
215	            } catch (Exception e) {
216	                ctx.status(500).json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
217	            }
218	        });
219	
220	        // GET /reservations/{id}/document
221	        app.get("/reservations/:id/document", ctx -> {
222	            try {
223	                long id = Long.parseLong(ctx.pathParam("id"));
224	                var document = reservationService.getDocument(id);
225	                ctx.json(DocumentResponse.fromModel(document));
226	            } catch (IllegalArgumentException e) {
227	                if (e.getMessage().contains("not found")) {
228	                    ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
229	                } else {
230	                    ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
231	                }
232	            } catch (Exception e) {
233	                ctx.status(500).json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
234	            }
235	        });
236	
237	        // GET /messages
238	        app.get("/messages", ctx -> {
239	            try {
240	                var messages = messageRepository.findAll();
241	                ctx.json(messages.stream().map(MessageResponse::fromModel).toList());
242	            } catch (Exception e) {
243	                ctx.status(500).json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
244	            }
245	        });
246	
247	        // GET /reports/occupancy
248	        app.get("/reports/occupancy", ctx -> {
249	            try {
250	                String dateStr = ctx.queryParam("date");
251	                if (dateStr == null) {
252	                    ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "date parameter is required"));
253	                    return;
254	                }
255	                LocalDate date = LocalDate.parse(dateStr);
256	                String csv = reportService.generateOccupancyReport(date);
257	                ctx.contentType("text/csv; charset=utf-8").result(csv);
258	            } catch (Exception e) {
259	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
260	            }
261	        });
262	
263	        // GET /reports/revenue
264	        app.get("/reports/revenue", ctx -> {
265	            try {
266	                String monthStr = ctx.queryParam("month");
267	                if (monthStr == null) {
268	                    ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "month parameter is required"));
269	                    return;
270	                }
271	                String csv = reportService.generateRevenueReport(monthStr);
272	                ctx.contentType("text/csv; charset=utf-8").result(csv);
273	            } catch (Exception e) {
274	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
275	            }
276	        });
277	    }
278	
279	    private void validateCreateReservationRequest(CreateReservationRequest req) throws Exception {
280	        if (req.guestName == null || req.guestName.isBlank() ||
281	            req.guestEmail == null || req.guestEmail.isBlank() ||
282	            req.checkIn == null || req.checkIn.isBlank() ||
283	            req.checkOut == null || req.checkOut.isBlank() ||
284	            req.ratePlan == null || req.ratePlan.isBlank()) {
285	            throw new IllegalArgumentException("Missing required fields");
286	        }
287	
288	        try {
289	            LocalDate.parse(req.checkIn);
290	            LocalDate.parse(req.checkOut);
291	        } catch (Exception e) {
292	            throw new IllegalArgumentException("Invalid date format");
293	        }
294	
295	        try {
296	            RatePlan.fromValue(req.ratePlan);
297	        } catch (Exception e) {
298	            throw new IllegalArgumentException("Invalid rate plan");
299	        }
300	    }
301	}

