256	                String csv = reportService.generateOccupancyReport(date);
257	                ctx.contentType("text/csv; charset=utf-8").result(csv);
258	            } catch (Exception e) {
259	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
260	            }
261	        });
262	
263	        // GET /reports/revenue
264	        app.get("/reports/revenue", ctx -> {
265	            try {
266	                String monthStr = ctx.queryParam("month");
267	                if (monthStr == null) {
268	                    ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "month parameter is required"));
269	                    return;
270	                }
271	                String csv = reportService.generateRevenueReport(monthStr);
272	                ctx.contentType("text/csv; charset=utf-8").result(csv);
273	            } catch (Exception e) {
274	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
275	            }
276	        });
277	    }
278	
279	    private void validateCreateReservationRequest(CreateReservationRequest req) throws Exception {
280	        if (req.guestName == null || req.guestName.isBlank() ||
281	            req.guestEmail == null || req.guestEmail.isBlank() ||
282	            req.checkIn == null || req.checkIn.isBlank() ||
283	            req.checkOut == null || req.checkOut.isBlank() ||
284	            req.ratePlan == null || req.ratePlan.isBlank()) {
285	            throw new IllegalArgumentException("Missing required fields");
286	        }
287	
288	        try {
289	            LocalDate.parse(req.checkIn);
290	            LocalDate.parse(req.checkOut);
291	        } catch (Exception e) {
292	            throw new IllegalArgumentException("Invalid date format");
293	        }
294	
295	        try {
296	            RatePlan.fromValue(req.ratePlan);
297	        } catch (Exception e) {
298	            throw new IllegalArgumentException("Invalid rate plan");
299	        }
300	    }
301	}

