 36	    public Reservation createReservation(
 37	            int roomNumber, String guestName, String guestEmail,
 38	            String guestCpf, String companyCnpj, String companyName,
 39	            String guestPassport, String guestCountry,
 40	            LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) throws Exception {
 41	
 42	        // Validate inputs
 43	        if (guests < 1) {
 44	            throw new IllegalArgumentException("At least one guest is required");
 45	        }
 46	        if (!checkIn.isBefore(checkOut)) {
 47	            throw new IllegalArgumentException("Check-out must be after check-in");
 48	        }
 49	
 50	        // Validate identification
 51	        int identificationCount = (guestCpf != null ? 1 : 0) +
 52	                                  (companyCnpj != null ? 1 : 0) +
 53	                                  (guestPassport != null ? 1 : 0);
 54	        if (identificationCount != 1) {
 55	            throw new IllegalArgumentException("Exactly one identification type is required");
 56	        }
 57	
 58	        // Check room exists and capacity
 59	        Room room = roomRepository.findById(roomNumber)
 60	                .orElseThrow(() -> new IllegalArgumentException("Room not found"));
 61	
 62	        if (guests > room.getCapacity()) {
 63	            throw new IllegalArgumentException("Guest count exceeds room capacity");
 64	        }
 65	
 66	        // Check room availability
 67	        if (!isRoomAvailable(roomNumber, checkIn, checkOut)) {
 68	            throw new IllegalArgumentException("Room is not available for selected dates");
 69	        }
 70	
 71	        // Calculate prices
 72	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
 73	        BigDecimal subtotal = calculateSubtotal(room, checkIn, checkOut);
 74	        BigDecimal discount = calculateDiscount(subtotal, ratePlan);
 75	        BigDecimal total = subtotal.subtract(discount);
 76	
 77	        // Create reservation
 78	        Reservation reservation = new Reservation(
 79	                0, roomNumber, guestName, guestEmail,
 80	                guestCpf, companyCnpj, companyName, guestPassport, guestCountry,
 81	                checkIn, checkOut, guests, ratePlan,
 82	                nights, subtotal, discount, total,
 83	                ReservationStatus.PENDING, BigDecimal.ZERO, null);
 84	
 85	        return reservationRepository.create(reservation);
 86	    }
