111	            reservation.getStatus() == ReservationStatus.CANCELLED) {
112	            throw new IllegalArgumentException("Cannot cancel this reservation");
113	        }
114	
115	        BigDecimal refund = null;
116	        if (reservation.getStatus() == ReservationStatus.CONFIRMED) {
117	            // STANDARD: full refund, NON_REFUNDABLE: no refund
118	            if (reservation.getRatePlan() == RatePlan.STANDARD) {
119	                refund = reservation.getAmountPaid();
120	            } else {
121	                refund = BigDecimal.ZERO;
