141	        reservationRepository.update(checkedIn);
142	        return checkedIn;
143	    }
144	
145	    public Document checkOut(long reservationId) throws Exception {
146	        Reservation reservation = getReservation(reservationId);
147	
148	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
149	            throw new IllegalArgumentException("Only checked-in reservations can check out");
150	        }
151	
152	        Reservation checkedOut = reservation.withStatus(ReservationStatus.CHECKED_OUT);
153	        reservationRepository.update(checkedOut);
154	
155	        return generateDocument(checkedOut);
156	    }
157	
158	    public Document getDocument(long reservationId) throws Exception {
159	        Reservation reservation = getReservation(reservationId);
160	
161	        if (reservation.getStatus() != ReservationStatus.CONFIRMED &&
162	            reservation.getStatus() != ReservationStatus.CHECKED_IN &&
163	            reservation.getStatus() != ReservationStatus.CHECKED_OUT) {
164	            throw new IllegalArgumentException("Document is only available for paid reservations");
165	        }
166	
167	        return generateDocument(reservation);
168	    }
169	
170	    public Reservation getReservation(long id) throws Exception {
171	        return reservationRepository.findById(id)
172	                .orElseThrow(() -> new IllegalArgumentException("Reservation not found"));
173	    }
174	
175	    private boolean isRoomAvailable(int roomNumber, LocalDate checkIn, LocalDate checkOut) throws Exception {
176	        List<Reservation> conflicts = reservationRepository.findByRoomAndDateRange(roomNumber, checkIn, checkOut);
177	        return conflicts.isEmpty();
178	    }
179	
180	    private BigDecimal calculateSubtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
181	        BigDecimal subtotal = BigDecimal.ZERO;
182	        LocalDate current = checkIn;
183	
184	        while (current.isBefore(checkOut)) {
185	            BigDecimal nightlyRate = room.getNightlyRate();
186	            BigDecimal multiplier = DateUtil.getSeasonMultiplier(current);
187	            BigDecimal nightPrice = nightlyRate.multiply(multiplier);
188	            nightPrice = NumberFormatter.round(nightPrice);
189	            subtotal = subtotal.add(nightPrice);
190	            current = current.plusDays(1);
191	        }
192	
193	        return NumberFormatter.round(subtotal);
194	    }
195	
196	    private BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
197	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
198	            BigDecimal discount = subtotal.multiply(new BigDecimal("0.15"));
199	            return NumberFormatter.round(discount);
200	        }
201	        return BigDecimal.ZERO;
202	    }
203	
204	    private Document generateDocument(Reservation reservation) throws Exception {
205	        Room room = roomRepository.findById(reservation.getRoomNumber())
206	                .orElseThrow(() -> new IllegalArgumentException("Room not found"));
207	
208	        DocumentData data = new DocumentData(
209	                reservation.getId(),
210	                reservation.getGuestName(),
211	                reservation.getGuestCpf(),
212	                reservation.getCompanyCnpj(),
213	                reservation.getCompanyName(),
214	                reservation.getGuestPassport(),
215	                reservation.getGuestCountry(),
216	                reservation.getRoomNumber(),
217	                room.getType().getValue(),
218	                reservation.getCheckIn(),
219	                reservation.getCheckOut(),
220	                reservation.getNights(),
221	                reservation.getSubtotal(),
222	                reservation.getDiscount(),
223	                reservation.getTotal()
224	        );
225	
226	        DocumentFormatter formatter = DocumentFormatterFactory.getFormatter(
227	                reservation.getGuestCpf(),
228	                reservation.getCompanyCnpj(),
229	                reservation.getGuestPassport()
230	        );
231	
232	        return formatter.format(data);
233	    }
234	
235	    private void sendConfirmationEmail(Reservation reservation) throws Exception {
236	        Document document = generateDocument(reservation);
237	
238	        String subject = "Reserva confirmada - Pousada Maré Alta";
239	        String body = buildEmailBody(reservation, document);
240	
241	        messageRepository.create("EMAIL", reservation.getGuestEmail(), subject, body);
242	    }
243	
244	    private String buildEmailBody(Reservation reservation, Document document) {
245	        StringBuilder body = new StringBuilder();
246	        body.append("Olá, ").append(reservation.getGuestName()).append("!\n\n");
247	        body.append("Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n");
248	        body.append(document.getText()).append("\n\n");
249	        body.append("A entrada é a partir das 14h, e a saída, até as 12h.\n");
250	        body.append("Até breve!");
251	
252	        return body.toString();
253	    }
254	}
