255	package com.pousada.mare_alta.service;
256	
257	import com.pousada.mare_alta.model.Reservation;
258	import com.pousada.mare_alta.model.Room;
259	import com.pousada.mare_alta.repository.ReservationRepository;
260	import com.pousada.mare_alta.repository.RoomRepository;
261	import com.pousada.mare_alta.util.NumberFormatter;
262	import java.math.BigDecimal;
263	import java.time.LocalDate;
264	import java.time.YearMonth;
265	import java.time.format.DateTimeFormatter;
266	import java.util.List;
267	
268	public class ReportService {
269	    private final ReservationRepository reservationRepository;
270	    private final RoomRepository roomRepository;
271	
272	    public ReportService(ReservationRepository reservationRepository, RoomRepository roomRepository) {
273	        this.reservationRepository = reservationRepository;
274	        this.roomRepository = roomRepository;
275	    }
276	
277	    public String generateOccupancyReport(LocalDate date) throws Exception {
278	        List<Reservation> reservations = reservationRepository.findPaidByNightOrderedByRoom(date);
279	        List<Room> allRooms = roomRepository.findAll();
280	
281	        StringBuilder csv = new StringBuilder();
282	        csv.append("room,type,reservation,check_in,check_out\n");
283	
284	        for (Room room : allRooms) {
285	            boolean found = false;
286	            for (Reservation res : reservations) {
287	                if (res.getRoomNumber() == room.getNumber()) {
288	                    DateTimeFormatter dateFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd");
289	                    csv.append(room.getNumber()).append(",");
290	                    csv.append(room.getType().getValue()).append(",");
291	                    csv.append(res.getId()).append(",");
292	                    csv.append(res.getCheckIn().format(dateFormatter)).append(",");
293	                    csv.append(res.getCheckOut().format(dateFormatter)).append("\n");
294	                    found = true;
295	                    break;
296	                }
297	            }
298	        }
299	
300	        int occupiedRooms = (int) reservations.stream()
301	                .map(Reservation::getRoomNumber)
302	                .distinct()
303	                .count();
304	
305	        csv.append("total,").append(occupiedRooms).append("/").append(allRooms.size()).append("\n");
306	
307	        return csv.toString();
308	    }
309	
310	    public String generateRevenueReport(String yearMonth) throws Exception {
311	        YearMonth ym = YearMonth.parse(yearMonth);
312	        List<Reservation> reservations = reservationRepository.findPaidByMonthOrderedByDate(
313	                ym.getYear(), ym.getMonthValue());
314	
315	        StringBuilder csv = new StringBuilder();
316	        csv.append("reservation,room,check_in,check_out,status,amount\n");
317	
318	        BigDecimal totalAmount = BigDecimal.ZERO;
319	        DateTimeFormatter dateFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd");
320	
321	        for (Reservation res : reservations) {
322	            csv.append(res.getId()).append(",");
323	            csv.append(res.getRoomNumber()).append(",");
324	            csv.append(res.getCheckIn().format(dateFormatter)).append(",");
325	            csv.append(res.getCheckOut().format(dateFormatter)).append(",");
326	            csv.append(res.getStatus().getValue()).append(",");
327	
328	            BigDecimal amount = calculateRevenueAmount(res);
329	            csv.append(NumberFormatter.formatCurrencyForCsv(amount)).append("\n");
330	            totalAmount = totalAmount.add(amount);
331	        }
332	
333	        csv.append("total,").append(NumberFormatter.formatCurrencyForCsv(totalAmount)).append("\n");
334	
335	        return csv.toString();
336	    }
337	
338	    private BigDecimal calculateRevenueAmount(Reservation res) {
339	        BigDecimal amount = res.getAmountPaid();
340	        if (res.getRefund() != null && res.getRefund().signum() > 0) {
341	            amount = amount.subtract(res.getRefund());
342	        }
343	        return amount;
344	    }
345	}

