     9	public class CnpjDocumentFormatter implements DocumentFormatter {
    10	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    11	    private static final BigDecimal ISS_RATE = new BigDecimal("0.05");
    12	
    13	    @Override
    14	    public Document format(DocumentData data) {
    15	        String nightsText = data.getNights() == 1 ? "1 diária" : data.getNights() + " diárias";
    16	        BigDecimal iss = calculateIss(data.getTotal());
    17	
    18	        StringBuilder text = new StringBuilder();
    19	        text.append("Fatura de hospedagem nº ").append(data.getReservationId()).append("\n");
    20	        text.append("Empresa: ").append(data.getCompanyName()).append(" (CNPJ ").append(formatCnpj(data.getCompanyCnpj())).append(")\n");
    21	        text.append("Hóspede: ").append(data.getGuestName()).append("\n");
    22	        text.append("Quarto: ").append(data.getRoomNumber()).append(" (").append(data.getRoomType()).append(")\n");
    23	        text.append("Entrada: ").append(data.getCheckIn().format(DATE_FORMATTER));
    24	        text.append(" | Saída: ").append(data.getCheckOut().format(DATE_FORMATTER));
    25	        text.append(" | ").append(nightsText).append("\n");
    26	        text.append("Diárias: ").append(NumberFormatter.formatCurrency(data.getSubtotal())).append("\n");
    27	
    28	        if (data.getDiscount().signum() > 0) {
    29	            text.append("Desconto: ").append(NumberFormatter.formatCurrency(data.getDiscount())).append("\n");
    30	        }
    31	
    32	        text.append("Total: ").append(NumberFormatter.formatCurrency(data.getTotal())).append("\n");
    33	        text.append("ISS retido (5%): ").append(NumberFormatter.formatCurrency(iss)).append("\n");
    34	
    35	        return new Document(
    36	                "Fatura de hospedagem",
    37	                data.getReservationId(), data.getGuestName(),
    38	                null, data.getCompanyCnpj(), data.getCompanyName(), null, null,
    39	                data.getRoomNumber(), data.getRoomType(),
    40	                data.getCheckIn(), data.getCheckOut(), data.getNights(),
    41	                data.getSubtotal(), data.getDiscount(), data.getTotal(),
    42	                text.toString().trim());
    43	    }
    44	
    45	    private BigDecimal calculateIss(BigDecimal total) {
    46	        return total.multiply(ISS_RATE).setScale(2, RoundingMode.HALF_EVEN);
    47	    }
    48	
    49	    private String formatCnpj(String cnpj) {
    50	        if (cnpj == null || cnpj.length() != 14) {
    51	            return cnpj;
    52	        }
    53	        return cnpj.substring(0, 2) + "." + cnpj.substring(2, 5) + "." + cnpj.substring(5, 8) + "/" + cnpj.substring(8, 12) + "-" + cnpj.substring(12);
    54	    }
    55	}
