  8	public class Database {
  9	    private final String url;
 10	    private final String user;
 11	    private final String password;
 12	
 13	    public Database(String url, String user, String password) {
 14	        this.url = url;
 15	        this.user = user;
 16	        this.password = password;
 17	    }
 18	
 19	    public void initialize() throws SQLException {
 20	        createTables();
 21	    }
 22	
 23	    public Connection getConnection() throws SQLException {
 24	        return DriverManager.getConnection(url, user, password);
 25	    }
 26	
 27	    private void createTables() throws SQLException {
 28	        try (Connection conn = getConnection();
 29	             Statement stmt = conn.createStatement()) {
 30	
 31	            // Rooms table
 32	            stmt.execute("""
 33	                CREATE TABLE IF NOT EXISTS rooms (
 34	                    number INTEGER PRIMARY KEY,
 35	                    type VARCHAR(50) NOT NULL,
 36	                    capacity INTEGER NOT NULL,
 37	                    nightly_rate NUMERIC(10, 2) NOT NULL
 38	                )
 39	                """);
 40	
 41	            // Reservations table
 42	            stmt.execute("""
 43	                CREATE TABLE IF NOT EXISTS reservations (
 44	                    id SERIAL PRIMARY KEY,
 45	                    room_number INTEGER NOT NULL REFERENCES rooms(number),
 46	                    guest_name VARCHAR(255) NOT NULL,
 47	                    guest_email VARCHAR(255) NOT NULL,
 48	                    guest_cpf VARCHAR(11),
 49	                    company_cnpj VARCHAR(14),
 50	                    company_name VARCHAR(255),
 51	                    guest_passport VARCHAR(50),
 52	                    guest_country VARCHAR(100),
 53	                    check_in DATE NOT NULL,
 54	                    check_out DATE NOT NULL,
 55	                    guests INTEGER NOT NULL,
 56	                    rate_plan VARCHAR(50) NOT NULL,
 57	                    nights INTEGER NOT NULL,
 58	                    subtotal NUMERIC(10, 2) NOT NULL,
 59	                    discount NUMERIC(10, 2) NOT NULL DEFAULT 0,
 60	                    total NUMERIC(10, 2) NOT NULL,
 61	                    status VARCHAR(50) NOT NULL,
 62	                    amount_paid NUMERIC(10, 2) NOT NULL DEFAULT 0,
 63	                    refund NUMERIC(10, 2)
 64	                )
 65	                """);
 66	
 67	            // Messages table
 68	            stmt.execute("""
 69	                CREATE TABLE IF NOT EXISTS messages (
 70	                    id SERIAL PRIMARY KEY,
 71	                    channel VARCHAR(50) NOT NULL,
 72	                    to_address VARCHAR(255) NOT NULL,
 73	                    subject VARCHAR(255) NOT NULL,
 74	                    body TEXT NOT NULL
 75	                )
 76	                """);
 77	
 78	            // Insert default rooms if not exist
 79	            insertDefaultRooms(stmt);
 80	        }
 81	    }
 82	
 83	    private void insertDefaultRooms(Statement stmt) throws SQLException {
 84	        stmt.execute("""
 85	            INSERT INTO rooms (number, type, capacity, nightly_rate)
