115	    public Message create(String channel, String to, String subject, String body) throws SQLException {
116	        String sql = """
117	            INSERT INTO messages (channel, to_address, subject, body)
118	            VALUES (?, ?, ?, ?)
119	            """;
120	
121	        try (Connection conn = database.getConnection();
