187	    public Reservation create(Reservation reservation) throws SQLException {
188	        String sql = """
189	            INSERT INTO reservations (
190	                room_number, guest_name, guest_email, guest_cpf,
191	                company_cnpj, company_name, guest_passport, guest_country,
192	                check_in, check_out, guests, rate_plan, nights,
193	                subtotal, discount, total, status, amount_paid, refund
194	            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
195	            """;
196	
197	        try (Connection conn = database.getConnection();
198	             PreparedStatement stmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
199	
200	            stmt.setInt(1, reservation.getRoomNumber());
201	            stmt.setString(2, reservation.getGuestName());
202	            stmt.setString(3, reservation.getGuestEmail());
203	            stmt.setString(4, reservation.getGuestCpf());
204	            stmt.setString(5, reservation.getCompanyCnpj());
205	            stmt.setString(6, reservation.getCompanyName());
206	            stmt.setString(7, reservation.getGuestPassport());
207	            stmt.setString(8, reservation.getGuestCountry());
208	            stmt.setDate(9, Date.valueOf(reservation.getCheckIn()));
209	            stmt.setDate(10, Date.valueOf(reservation.getCheckOut()));
210	            stmt.setInt(11, reservation.getGuests());
211	            stmt.setString(12, reservation.getRatePlan().getValue());
212	            stmt.setInt(13, reservation.getNights());
213	            stmt.setBigDecimal(14, reservation.getSubtotal());
214	            stmt.setBigDecimal(15, reservation.getDiscount());
215	            stmt.setBigDecimal(16, reservation.getTotal());
216	            stmt.setString(17, reservation.getStatus().getValue());
217	            stmt.setBigDecimal(18, reservation.getAmountPaid());
218	            stmt.setObject(19, reservation.getRefund());
219	
220	            stmt.executeUpdate();
221	
222	            ResultSet generatedKeys = stmt.getGeneratedKeys();
223	            if (generatedKeys.next()) {
224	                long id = generatedKeys.getLong(1);
225	                return findById(id).orElseThrow();
226	            }
227	            throw new SQLException("Failed to create reservation");
228	        }
229	    }
