231	    public Optional<Reservation> findById(long id) throws SQLException {
232	        try (Connection conn = database.getConnection();
233	             PreparedStatement stmt = conn.prepareStatement("SELECT * FROM reservations WHERE id = ?")) {
234	            stmt.setLong(1, id);
