261	    public List<Reservation> findByRoomAndDateRange(int roomNumber, LocalDate from, LocalDate to) throws SQLException {
262	        List<Reservation> reservations = new ArrayList<>();
263	        String sql = """
264	            SELECT * FROM reservations
