 31	
 32	public class DateUtil {
 33	    private static final LocalDate HIGH_SEASON_START_1 = LocalDate.of(2024, 12, 15);
 34	    private static final LocalDate HIGH_SEASON_END_1 = LocalDate.of(2025, 2, 28);
 35	    private static final int HIGH_SEASON_MONTH = 7;
 36	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
 37	    private static final BigDecimal NORMAL_MULTIPLIER = new BigDecimal("1.00");
 38	
 39	    public static boolean isHighSeason(LocalDate date) {
 40	        // Check if date is in July
 41	        if (date.getMonthValue() == HIGH_SEASON_MONTH) {
 42	            return true;
 43	        }
 44	
 45	        // Check if date is between Dec 15 and Feb 28 (accounting for year changes)
 46	        int month = date.getMonthValue();
 47	        int day = date.getDayOfMonth();
 48	
 49	        if (month == 12 && day >= 15) {
 50	            return true;
 51	        }
 52	        if (month == 1 || month == 2) {
 53	            return true;
 54	        }
 55	
 56	        return false;
 57	    }
 58	
 59	    public static BigDecimal getSeasonMultiplier(LocalDate date) {
 60	        return isHighSeason(date) ? HIGH_SEASON_MULTIPLIER : NORMAL_MULTIPLIER;
 61	    }
 62	
 63	    public static YearMonth parseYearMonth(String yearMonth) {
 64	        return YearMonth.parse(yearMonth);
 65	    }
 66	}
